import AppKit
import MeetMuteCore

/// Plays a short cue after a stem press changes Meet's mic: high→low for mute,
/// low→high for unmute (Support/Sounds, regenerated by scripts/make-sounds.sh).
/// The system's own mute and unmute chimes sound alike; these make the direction obvious.
final class PressFeedbackSound {
    private let muteSound = NSSound(named: "Mute")
    private let unmuteSound = NSSound(named: "Unmute")

    /// Returns an error message when the sound is missing from the app bundle.
    @discardableResult
    func play(for state: MicState) -> String? {
        let sound = state == .muted ? muteSound : unmuteSound
        guard let sound else {
            return "Press sound missing from the app bundle — rebuild with scripts/build-app.sh"
        }
        sound.stop()  // restart cleanly if the previous press's cue is still playing
        sound.play()
        return nil
    }
}
